function ProvinceBadge({ name, index }) {
    const badges = [
        { bg: 'rgba(255,255,255,0.22)', border: 'rgba(255,255,255,0.35)' },
        { bg: 'rgba(255,255,255,0.18)', border: 'rgba(255,255,255,0.3)' },
        { bg: 'rgba(255,255,255,0.15)', border: 'rgba(255,255,255,0.25)' },
        { bg: 'rgba(255,255,255,0.12)', border: 'rgba(255,255,255,0.2)' },
    ];
    const b = badges[index % badges.length];
    const initials = (name || 'ID')
        .split(' ')
        .filter(Boolean)
        .slice(0, 2)
        .map(w => w[0])
        .join('')
        .toUpperCase();

    return (
        <div
            style={{
                width: 28,
                height: 22,
                borderRadius: 6,
                background: b.bg,
                border: `1px solid ${b.border}`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '0.65rem',
                fontWeight: 800,
                color: '#ffffff',
                flexShrink: 0,
                letterSpacing: '0.03em',
            }}
        >
            {initials}
        </div>
    );
}

